@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=DM+Sans:wght@500;700&display=swap');

:root{
  --bg: oklch(0.98 0.02 95);
  --surface: oklch(0.995 0.01 95);
  --text: oklch(0.30 0.03 65);
  --muted: oklch(0.58 0.03 70);
  --primary: oklch(0.50 0.10 150);
  --primary-2: oklch(0.42 0.08 145);
  --accent: oklch(0.70 0.10 80);
  --coffee: oklch(0.44 0.06 60);
  --border: oklch(0.88 0.02 85);
  --shadow: 0 10px 30px color-mix(in oklab, var(--coffee) 12%, transparent);
  --radius: 18px;
  --container: 1180px;
}
*{box-sizing:border-box}
html,body{margin:0;padding:0}
body{
  font-family:'Inter',system-ui,-apple-system,sans-serif;
  color:var(--text);
  background:
    radial-gradient(1200px 500px at 0% -10%, color-mix(in oklab,var(--primary) 12%, white), transparent 60%),
    radial-gradient(1000px 500px at 100% 0%, color-mix(in oklab,var(--accent) 12%, white), transparent 60%),
    var(--bg);
  line-height:1.55;
}
h1,h2,h3,h4{font-family:'DM Sans','Inter',sans-serif;line-height:1.15;margin:0 0 .7rem}
a{text-decoration:none;color:inherit}
img{max-width:100%;display:block}
.container{max-width:var(--container);margin:0 auto;padding:0 1rem}
.section{padding:4rem 0}
.card{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);box-shadow:var(--shadow)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.5rem;padding:.8rem 1.2rem;border-radius:999px;font-weight:700;border:1px solid transparent;cursor:pointer;transition:all .2s ease;min-height:44px}
.btn:hover{transform:translateY(-2px)}
.btn:active{transform:scale(.98)}
.btn-primary{background:var(--primary);color:white}
.btn-primary:hover{background:var(--primary-2)}
.btn-ghost{background:transparent;border-color:var(--border)}
.topbar{position:sticky;top:0;z-index:30;background:color-mix(in oklab,var(--surface) 92%, white);backdrop-filter:blur(8px);border-bottom:1px solid var(--border)}
.nav{display:flex;align-items:center;justify-content:space-between;padding:.8rem 0}
.logo{display:flex;align-items:center;gap:.65rem;font-weight:800}
.logo-badge{width:36px;height:36px;border-radius:50%;display:grid;place-items:center;background:linear-gradient(135deg,var(--primary),var(--coffee));color:white;font-size:1.1rem}
.nav-links{display:flex;gap:1rem;align-items:center;flex-wrap:wrap}
.nav-links a{padding:.5rem .7rem;border-radius:999px;font-weight:600;color:var(--muted)}
.nav-links a.active,.nav-links a:hover{background:color-mix(in oklab,var(--primary) 18%, white);color:var(--primary-2)}
.hero{display:grid;gap:2rem;grid-template-columns:1.15fr .85fr;align-items:center}
.hero-copy h1{font-size:clamp(2rem,6vw,3.6rem)}
.hero-copy p{color:var(--muted);max-width:58ch}
.hero-cta{display:flex;gap:.8rem;flex-wrap:wrap;margin-top:1.1rem}
.hero-media{border-radius:28px;overflow:hidden;min-height:340px;position:relative}
.hero-media img{width:100%;height:100%;object-fit:cover}
.badge{display:inline-flex;align-items:center;gap:.4rem;padding:.35rem .65rem;border-radius:999px;background:color-mix(in oklab,var(--accent) 25%, white);font-weight:700;font-size:.82rem}
.grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}
.grid-2{display:grid;grid-template-columns:repeat(2,1fr);gap:1rem}
.footer{background:color-mix(in oklab,var(--surface) 70%, var(--bg));border-top:1px solid var(--border);margin-top:3rem}
.footer-columns{display:grid;grid-template-columns:repeat(5,1fr);gap:1rem;padding:2rem 0}
.footer h4{font-size:1rem;margin-bottom:.6rem}
.footer a{display:block;padding:.25rem 0;color:var(--muted)}
.cookie{position:fixed;left:1rem;right:1rem;bottom:1rem;z-index:80;padding:1rem;display:flex;gap:1rem;align-items:center;justify-content:space-between}
.cookie.hidden{display:none}
.tabs{display:flex;flex-wrap:wrap;gap:.6rem}
.tab-btn{padding:.55rem .9rem;border-radius:999px;border:1px solid var(--border);background:transparent;font-weight:700;cursor:pointer}
.tab-btn.active{background:var(--primary);color:white;border-color:var(--primary)}
.tab-panel{display:none;padding:1rem 0}
.tab-panel.active{display:block;animation:fadeUp .3s ease}
@keyframes fadeUp{from{opacity:.4;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
.carousel{position:relative;overflow:hidden}
.carousel-track{display:flex;transition:transform .35s ease}
.slide{min-width:100%;padding:.3rem}
.carousel-nav{display:flex;gap:.5rem}
.icon-btn{width:42px;height:42px;border-radius:50%;border:1px solid var(--border);background:var(--surface);cursor:pointer}
.menu-layout{display:grid;grid-template-columns:260px 1fr;gap:1rem}
.sidebar a{display:block;padding:.65rem .75rem;border-radius:10px;color:var(--muted);font-weight:600}
.sidebar a:hover,.sidebar a.active{background:color-mix(in oklab,var(--primary) 18%, white);color:var(--primary-2)}
.locator-layout{display:grid;grid-template-columns:360px 1fr;gap:1rem}
.input{width:100%;padding:.75rem .9rem;border-radius:12px;border:1px solid var(--border);background:white}
.pill-toggle{display:inline-flex;background:white;border:1px solid var(--border);border-radius:999px;padding:.25rem}
.pill-toggle button{border:0;background:transparent;padding:.45rem .8rem;border-radius:999px;cursor:pointer;font-weight:700}
.pill-toggle button.active{background:var(--primary);color:white}
.suggestions{margin:.6rem 0 0;display:none;border:1px solid var(--border);border-radius:12px;background:white;overflow:hidden}
.suggestions.show{display:block}
.suggestion{padding:.65rem .8rem;cursor:pointer;border-bottom:1px solid var(--border)}
.suggestion:last-child{border-bottom:0}
.mobile-acc-btn{display:none;width:100%;text-align:left;background:none;border:0;padding:.2rem 0 .6rem;font:inherit;font-weight:700}
@media (max-width: 992px){
  .hero{grid-template-columns:1fr}
  .grid-3{grid-template-columns:1fr 1fr}
  .footer-columns{grid-template-columns:repeat(2,1fr)}
  .menu-layout,.locator-layout{grid-template-columns:1fr}
}
@media (max-width: 720px){
  .grid-3,.grid-2{grid-template-columns:1fr}
  .nav{align-items:flex-start;gap:.8rem;flex-direction:column}
  .footer-columns{grid-template-columns:1fr}
  .footer-group .links{display:none}
  .footer-group.open .links{display:block}
  .mobile-acc-btn{display:block}
}
EOF

